# Times a package-development loader on a package generated by generate.py: a cold load, then
# the reload after one function body changes, after one file gains a function, and with nothing
# changed. LOADER is pkgload, loadfast or ry, PKG the package root; R_LIBS must hold pkgload and
# loadfast. Run the ry case through ry itself, which provides `load_all()`: `ry R` runs it on GNU R
# and `ry run` on ry's own runtime:
#
#   python3 generate.py medium 80 12 /tmp/medium
#   LOADER=pkgload PKG=/tmp/medium Rscript bench.R
#   LOADER=loadfast PKG=/tmp/medium Rscript bench.R
#   LOADER=ry PKG=/tmp/medium ry R bench.R
#   LOADER=ry PKG=/tmp/medium ry run bench.R
#
# The large package of the loading-packages docs page is `generate.py large 500 46 <dir>`.
# The script edits R/file0001.R and restores it at the end.
options(keep.source = FALSE)  # what Rscript runs pkgload and loadfast with
loader <- Sys.getenv("LOADER")
root <- normalizePath(Sys.getenv("PKG"))
load <- switch(loader,
  pkgload = function() pkgload::load_all(root, quiet = TRUE, helpers = FALSE),
  loadfast = function() suppressMessages(loadfast::load_fast(root, helpers = FALSE)),
  ry = function() load_all(root, quiet = TRUE)
)
time <- function() system.time(load())[["elapsed"]] * 1000
file <- file.path(root, "R", "file0001.R")
original <- readLines(file)
cold <- time(); options(ry.load.verbose = Sys.getenv("VERBOSE") == "1")
first_call <- system.time(f1_3(1:5))[["elapsed"]] * 1000
writeLines(sub("x \\* ([0-9])", "x * 10 + \\1", original), file)
body_edit <- time()
stopifnot(identical(f1_1(1)$n, 1L))
writeLines(c(readLines(file), "brand_new <- function() 1"), file)
new_function <- time()
stopifnot(identical(brand_new(), 1))
unchanged <- time()
writeLines(original, file)
cat(sprintf("%-9s cold %7.0f ms | body edit %6.0f ms | new function %6.0f ms | no change %6.0f ms\n",
            loader, cold, body_edit, new_function, unchanged))
